 *
 * `createContactsClient(service)` must return an object with `listAll()`, `get(id)` and `create(input)`.
 * See specification.md for the contract, and conformance/cases.mjs for exactly what is checked.
 */

const PAGE_SIZE = 3;

function serviceError(status, body) {
	const code = body?.error?.code ?? "unknown_error";
	const message = body?.error?.message ?? `request failed with status ${status}`;
	const err = new Error(message);
	err.name = "ServiceError";
	err.status = status;
	err.code = code;
	return err;
}

export function createContactsClient(service) {
	async function listAll() {
		const items = [];
		let cursor;
		for (;;) {
			const query = { limit: PAGE_SIZE };
			if (cursor !== undefined) query.cursor = cursor;
			const { status, body } = await service.request("GET", "/contacts", { query });
			if (status !== 200) throw serviceError(status, body);
			items.push(...body.items);
			if (body.nextCursor === null || body.nextCursor === undefined) break;
			cursor = body.nextCursor;
		}
		return items;
	}

	async function get(id) {
		const { status, body } = await service.request("GET", `/contacts/${id}`);
		if (status === 200) return body;
		if (status === 404 && body?.error?.code === "not_found") return null;
		throw serviceError(status, body);
	}

	async function create(input) {
		const { status, body } = await service.request("POST", "/contacts", { body: input });
		if (status === 201) return body;
		if (status === 422 && body?.error?.code === "validation_failed") {
			const err = new Error(body.error.message ?? "validation failed");
			err.name = "ValidationError";
			err.fields = body.error.fields ?? [];
			throw err;
		}
		throw serviceError(status, body);
	}

	return { listAll, get, create };
}
